}

// Claude returns a needs_more_info classification
function mockClaudeNeedsMoreInfo() {
  mockAnthropicCreate.mockResolvedValue({
    content: [{
      text: JSON.stringify({
        type: "question",
        priority: "medium",
        triage_summary: "Issue lacks reproduction steps.",
        labels: ["needs-info"],
        needs_more_info: true,
        duplicate_hint: null,
      }),
    }],
